    73	 */
    74	function write_drafts_payload(array $payload): void
    75	{
    76	  if (!isset($payload['meta']) || !is_array($payload['meta'])) {
    77	    $payload['meta'] = [];
    78	  }
    79	  if (!isset($payload['drafts']) || !is_array($payload['drafts'])) {
    80	    $payload['drafts'] = [];
    81	  }
    82	
    83	  if (!isset($payload['meta']['created_at'])) {
    84	    $payload['meta']['created_at'] = date('c');
    85	  }
    86	  $payload['meta']['updated_at'] = date('c');
    87	  $payload['meta']['count'] = count($payload['drafts']);
    88	
    89	  $json = json_encode($payload, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    90	  if ($json === false) {
    91	    throw new RuntimeException('Unable to encode draft payload.');
    92	  }
    93	  file_put_contents(ADMIN_DRAFTS_PATH, $json . PHP_EOL);
    94	}
